from __future__ import annotations

from typing import Any


def _finding_case(
    case_id: str,
    code: str,
    category: str,
    severity: str,
    line: int,
    title: str,
    language: str = "python",
) -> dict[str, Any]:
    return {
        "id": case_id,
        "language": language,
        "code": code,
        "expected": [
            {
                "category": category,
                "severity": severity,
                "line": line,
                "title": title,
            }
        ],
    }


def _clean_case(case_id: str, code: str, language: str = "python") -> dict[str, Any]:
    return {"id": case_id, "language": language, "code": code, "expected": []}


